ALTER TABLE public.financeiro_baixas ADD COLUMN IF NOT EXISTS estorno_de_id uuid REFERENCES public.financeiro_baixas(id);CREATE UNIQUE INDEX IF NOT EXISTS financeiro_baixas_estorno_unico ON public.financeiro_baixas(estorno_de_id) WHERE estorno_de_id IS NOT NULL;
CREATE OR REPLACE FUNCTION public.normalizar_lancamento_financeiro()RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$DECLARE f formas_pagamento%ROWTYPE;BEGIN NEW.competencia:=coalesce(NEW.competencia,date_trunc('month',NEW.vencimento)::date);NEW.valor_bruto:=coalesce(NEW.valor_bruto,NEW.valor);NEW.valor_liquido:=coalesce(NEW.valor_liquido,NEW.valor_bruto-coalesce(NEW.taxa,0));IF TG_TABLE_NAME='financeiro_recebimentos'AND NEW.forma_pagamento_id IS NULL AND NEW.forma_pagamento IS NOT NULL THEN SELECT * INTO f FROM formas_pagamento WHERE clinica_id=NEW.clinica_id AND lower(nome)=lower(NEW.forma_pagamento)LIMIT 1;IF f.id IS NOT NULL THEN NEW.forma_pagamento_id:=f.id;NEW.taxa:=round(NEW.valor_bruto*f.taxa_percentual/100+f.taxa_fixa,2);NEW.valor_liquido:=NEW.valor_bruto-NEW.taxa;NEW.previsto_credito_em:=NEW.vencimento+f.prazo_recebimento_dias;NEW.conta_financeira_id:=coalesce(NEW.conta_financeira_id,f.conta_financeira_id);END IF;END IF;IF TG_TABLE_NAME='financeiro_pagamentos'AND NEW.pedido_compra_id IS NOT NULL THEN NEW.origem_tipo:=coalesce(NEW.origem_tipo,'pedido_compra');NEW.origem_id:=coalesce(NEW.origem_id,NEW.pedido_compra_id);END IF;RETURN NEW;END $$;
CREATE TRIGGER trg_normalizar_recebimento BEFORE INSERT ON public.financeiro_recebimentos FOR EACH ROW EXECUTE FUNCTION public.normalizar_lancamento_financeiro();CREATE TRIGGER trg_normalizar_pagamento BEFORE INSERT ON public.financeiro_pagamentos FOR EACH ROW EXECUTE FUNCTION public.normalizar_lancamento_financeiro();
CREATE OR REPLACE FUNCTION public.criar_lancamentos_parcelados(p_tipo text,p_valor numeric,p_parcelas integer,p_primeiro_vencimento date,p_dia_vencimento integer,p_descricao text,p_unidade uuid DEFAULT NULL,p_paciente uuid DEFAULT NULL,p_profissional uuid DEFAULT NULL,p_conta uuid DEFAULT NULL,p_forma uuid DEFAULT NULL,p_origem_tipo text DEFAULT NULL,p_origem_id uuid DEFAULT NULL)RETURNS uuid[] LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$DECLARE v_clinica uuid:=current_clinica_id();v_ids uuid[]:='{}';v_base numeric(12,2);v_acum numeric(12,2):=0;v_valor numeric(12,2);v_mes date;v_venc date;v_id uuid;v_forma_nome text;BEGIN IF NOT tem_papel('owner','admin','financeiro','recepcao','dentista','esteticista')THEN RAISE EXCEPTION 'Sem permissão';END IF;IF p_tipo NOT IN('receber','pagar')OR(p_tipo='pagar'AND NOT tem_papel('owner','admin','financeiro'))THEN RAISE EXCEPTION 'Tipo ou permissão inválida';END IF;IF round(coalesce(p_valor,0),2)<=0 OR p_parcelas NOT BETWEEN 1 AND 48 OR p_dia_vencimento NOT BETWEEN 1 AND 31 THEN RAISE EXCEPTION 'Dados do parcelamento inválidos';END IF;IF p_unidade IS NOT NULL AND NOT EXISTS(SELECT 1 FROM unidades WHERE id=p_unidade AND clinica_id=v_clinica)THEN RAISE EXCEPTION 'Unidade inválida';END IF;IF p_conta IS NOT NULL AND NOT EXISTS(SELECT 1 FROM plano_contas WHERE id=p_conta AND clinica_id=v_clinica)THEN RAISE EXCEPTION 'Conta inválida';END IF;IF p_forma IS NOT NULL AND NOT EXISTS(SELECT 1 FROM formas_pagamento WHERE id=p_forma AND clinica_id=v_clinica)THEN RAISE EXCEPTION 'Forma de pagamento inválida';END IF;IF p_paciente IS NOT NULL AND NOT EXISTS(SELECT 1 FROM pacientes WHERE id=p_paciente AND clinica_id=v_clinica)THEN RAISE EXCEPTION 'Paciente inválido';END IF;IF p_profissional IS NOT NULL AND NOT EXISTS(SELECT 1 FROM profissionais WHERE id=p_profissional AND clinica_id=v_clinica)THEN RAISE EXCEPTION 'Profissional inválido';END IF;SELECT nome INTO v_forma_nome FROM formas_pagamento WHERE id=p_forma AND clinica_id=v_clinica;v_base:=trunc(round(p_valor,2)/p_parcelas,2);FOR i IN 1..p_parcelas LOOP v_valor:=CASE WHEN i=p_parcelas THEN round(p_valor,2)-v_acum ELSE v_base END;v_acum:=v_acum+v_valor;v_mes:=date_trunc('month',p_primeiro_vencimento)::date+make_interval(months=>i-1);v_venc:=v_mes+(least(p_dia_vencimento,extract(day from(v_mes+interval'1 month - 1 day'))::int)-1);IF p_tipo='receber'THEN INSERT INTO financeiro_recebimentos(clinica_id,unidade_id,paciente_id,profissional_id,conta_id,forma_pagamento_id,forma_pagamento,descricao,parcela,total_parcelas,valor,valor_bruto,valor_liquido,vencimento,competencia,origem_tipo,origem_id)VALUES(v_clinica,p_unidade,p_paciente,p_profissional,p_conta,p_forma,coalesce(v_forma_nome,'A definir'),p_descricao,i,p_parcelas,v_valor,v_valor,v_valor,v_venc,date_trunc('month',v_venc)::date,p_origem_tipo,p_origem_id)RETURNING id INTO v_id;ELSE INSERT INTO financeiro_pagamentos(clinica_id,unidade_id,conta_id,forma_pagamento_id,descricao,valor,valor_bruto,valor_liquido,vencimento,competencia,origem_tipo,origem_id)VALUES(v_clinica,p_unidade,p_conta,p_forma,p_descricao,v_valor,v_valor,v_valor,v_venc,date_trunc('month',v_venc)::date,p_origem_tipo,p_origem_id)RETURNING id INTO v_id;END IF;v_ids:=array_append(v_ids,v_id);END LOOP;RETURN v_ids;END $$;
CREATE OR REPLACE FUNCTION public.criar_lancamento_extrato(p_extrato uuid,p_descricao text,p_conta_plano uuid DEFAULT NULL)RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$DECLARE e extrato_bancario_itens%ROWTYPE;v_lanc uuid;v_baixa uuid;BEGIN IF NOT tem_papel('owner','admin','financeiro')THEN RAISE EXCEPTION 'Sem permissão';END IF;SELECT * INTO e FROM extrato_bancario_itens WHERE id=p_extrato FOR UPDATE;IF NOT FOUND OR e.clinica_id<>current_clinica_id()OR e.status<>'pendente'THEN RAISE EXCEPTION 'Item de extrato inválido';END IF;IF p_conta_plano IS NOT NULL AND NOT EXISTS(SELECT 1 FROM plano_contas WHERE id=p_conta_plano AND clinica_id=e.clinica_id)THEN RAISE EXCEPTION 'Conta contábil inválida';END IF;IF e.valor>0 THEN INSERT INTO financeiro_recebimentos(clinica_id,conta_id,conta_financeira_id,descricao,valor,vencimento,competencia,origem_tipo,origem_id)VALUES(e.clinica_id,p_conta_plano,e.conta_financeira_id,p_descricao,e.valor,e.data,date_trunc('month',e.data)::date,'extrato',e.id)RETURNING id INTO v_lanc;v_baixa:=registrar_baixa('receber',v_lanc,e.valor,e.conta_financeira_id,NULL,e.data);ELSE INSERT INTO financeiro_pagamentos(clinica_id,conta_id,conta_financeira_id,descricao,valor,vencimento,competencia,origem_tipo,origem_id)VALUES(e.clinica_id,p_conta_plano,e.conta_financeira_id,p_descricao,abs(e.valor),e.data,date_trunc('month',e.data)::date,'extrato',e.id)RETURNING id INTO v_lanc;v_baixa:=registrar_baixa('pagar',v_lanc,abs(e.valor),e.conta_financeira_id,NULL,e.data);END IF;PERFORM conciliar_extrato(e.id,v_baixa,'Lançamento criado a partir do extrato');RETURN v_lanc;END $$;
CREATE OR REPLACE FUNCTION public.relatorio_indicadores(p_inicio date,p_fim date,p_unidade uuid DEFAULT NULL)RETURNS jsonb LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$WITH rec AS(SELECT coalesce(sum(valor_bruto),0)faturamento,coalesce(sum(valor_pago),0)recebido,count(DISTINCT paciente_id)pacientes FROM financeiro_recebimentos WHERE clinica_id=current_clinica_id()AND status<>'cancelado'AND competencia BETWEEN date_trunc('month',p_inicio)::date AND date_trunc('month',p_fim)::date AND(p_unidade IS NULL OR unidade_id=p_unidade)),orc AS(SELECT count(*)total,count(*)FILTER(WHERE status IN('aprovado','em_execucao','concluido'))convertidos FROM orcamentos WHERE clinica_id=current_clinica_id()AND created_at::date BETWEEN p_inicio AND p_fim),inad AS(SELECT coalesce(sum(valor-valor_pago),0)valor FROM financeiro_recebimentos WHERE clinica_id=current_clinica_id()AND status='atrasado'AND(p_unidade IS NULL OR unidade_id=p_unidade))SELECT CASE WHEN tem_papel('owner','admin','financeiro')THEN jsonb_build_object('faturamento',rec.faturamento,'recebido',rec.recebido,'ticket_medio',CASE WHEN rec.pacientes>0 THEN round(rec.faturamento/rec.pacientes,2)ELSE 0 END,'conversao_orcamentos',CASE WHEN orc.total>0 THEN round(orc.convertidos::numeric*100/orc.total,2)ELSE 0 END,'inadimplencia',inad.valor)ELSE'{}'::jsonb END FROM rec CROSS JOIN orc CROSS JOIN inad$$;
CREATE OR REPLACE FUNCTION public.exportacao_contabil(p_inicio date,p_fim date)RETURNS TABLE(tipo text,data date,competencia date,descricao text,categoria text,documento text,valor_bruto numeric,taxa numeric,valor_liquido numeric,status text)LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$SELECT * FROM(SELECT 'Receita'::text tipo,r.vencimento data,r.competencia,r.descricao,pc.nome categoria,r.origem_tipo documento,r.valor_bruto,r.taxa,r.valor_liquido,r.status::text status FROM financeiro_recebimentos r LEFT JOIN plano_contas pc ON pc.id=r.conta_id WHERE r.clinica_id=current_clinica_id()AND r.competencia BETWEEN date_trunc('month',p_inicio)::date AND date_trunc('month',p_fim)::date UNION ALL SELECT 'Despesa'::text,p.vencimento,p.competencia,p.descricao,pc.nome,p.origem_tipo,p.valor_bruto,p.taxa,p.valor_liquido,p.status::text FROM financeiro_pagamentos p LEFT JOIN plano_contas pc ON pc.id=p.conta_id WHERE p.clinica_id=current_clinica_id()AND p.competencia BETWEEN date_trunc('month',p_inicio)::date AND date_trunc('month',p_fim)::date)x WHERE tem_papel('owner','admin','financeiro')ORDER BY 2,4$$;
REVOKE EXECUTE ON FUNCTION public.criar_lancamento_extrato(uuid,text,uuid),public.relatorio_indicadores(date,date,uuid),public.exportacao_contabil(date,date)FROM PUBLIC,anon;GRANT EXECUTE ON FUNCTION public.criar_lancamento_extrato(uuid,text,uuid),public.relatorio_indicadores(date,date,uuid),public.exportacao_contabil(date,date)TO authenticated;